    private int TotalItems => FilteredList.Count;
    private int TotalPages => Math.Max(1, (int)Math.Ceiling((double)TotalItems / pageSize));
    private List<HocBaRow> PagedList => FilteredList.Skip((currentPage - 1) * pageSize).Take(pageSize).ToList();

    // --- CHECKBOX LOGIC ---
    private int SelectedCount => FullList.Count(x => x.IsSelected);
    private bool IsAllSelected => PagedList.Any() && PagedList.All(x => x.IsSelected);

