    {
        bool isChecked = (bool)(e.Value ?? false);
        foreach (var item in PagedList)
        {
            item.IsSelected = isChecked;
        }
    }

    private void ChangePage(int newPage)
    {
        if (newPage >= 1 && newPage <= TotalPages) currentPage = newPage;
    }

